<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { fetchUserPage } from '@/services/organization'
import { createRole, disableRole, enableRole, fetchPermissionPage, fetchRole, fetchRolePage, fetchRolePermissions, fetchUserRoles, grantRolePermission, grantUserRole, revokeRolePermission, revokeUserRole, updateRole } from '@/services/rbac'
import type { Permission, Role, UserAccount } from '@/types/api'

const roles = ref<Role[]>([]); const permissions = ref<Permission[]>([]); const users = ref<UserAccount[]>([]); const loading = ref(false)
const roleVisible = ref(false); const permissionVisible = ref(false); const userRoleVisible = ref(false); const editing = ref(false); const selectedRole = ref<Role | null>(null); const selectedUser = ref<UserAccount | null>(null)
const grantedPermissionIds = ref<number[]>([]); const grantedRoleIds = ref<number[]>([])
const roleForm = reactive({ id: 0, roleCode: '', roleName: '', description: '' })
const activeRoles = computed(() => roles.value.filter((item) => item.status === 'ACTIVE'))
async function load() { loading.value = true; try { const [rolePage, permissionPage, userPage] = await Promise.all([fetchRolePage({ pageNum: 1, pageSize: 100 }), fetchPermissionPage({ pageNum: 1, pageSize: 100, status: 'ACTIVE' }), fetchUserPage({ pageNum: 1, pageSize: 100, status: 'ACTIVE' })]); roles.value = rolePage.records; permissions.value = permissionPage.records; users.value = userPage.records } finally { loading.value = false } }
function openCreate() { editing.value = false; Object.assign(roleForm, { id: 0, roleCode: '', roleName: '', description: '' }); roleVisible.value = true }
async function openEdit(value: unknown) { const row = value as Role; editing.value = true; Object.assign(roleForm, await fetchRole(row.id)); roleVisible.value = true }
async function saveRole() { if (!roleForm.roleName || (!editing.value && !roleForm.roleCode)) return ElMessage.warning('请填写完整角色信息'); if (editing.value) await updateRole({ id: roleForm.id, roleName: roleForm.roleName, description: roleForm.description }); else await createRole({ roleCode: roleForm.roleCode, roleName: roleForm.roleName, description: roleForm.description }); roleVisible.value = false; await load() }
async function removeRole(value: unknown) { const row = value as Role; await ElMessageBox.confirm(`确认停用 ${row.roleName}？`); await disableRole(row.id); await load() }
async function restoreRole(value: unknown) { const row = value as Role; await enableRole(row.id); ElMessage.success('角色已启用'); await load() }
async function openPermissions(value: unknown) { const row = value as Role; selectedRole.value = row; const relations = await fetchRolePermissions(row.id); grantedPermissionIds.value = relations.map((item) => item.permissionId); permissionVisible.value = true }
async function togglePermission(permissionId: number, checked: boolean) { if (!selectedRole.value) return; if (checked) await grantRolePermission(selectedRole.value.id, permissionId); else await revokeRolePermission(selectedRole.value.id, permissionId); const relations = await fetchRolePermissions(selectedRole.value.id); grantedPermissionIds.value = relations.map((item) => item.permissionId); ElMessage.success('角色权限已更新') }
async function openUserRoles(value: unknown) { const user = value as UserAccount; selectedUser.value = user; const relations = await fetchUserRoles(user.id); grantedRoleIds.value = relations.map((item) => item.roleId); userRoleVisible.value = true }
async function toggleUserRole(roleId: number, checked: boolean) { if (!selectedUser.value) return; if (checked) await grantUserRole(selectedUser.value.id, roleId); else await revokeUserRole(selectedUser.value.id, roleId); const relations = await fetchUserRoles(selectedUser.value.id); grantedRoleIds.value = relations.map((item) => item.roleId); ElMessage.success('用户角色已更新') }
onMounted(load)
</script>
<template><main class="workspace-page"><header class="page-heading"><div><span class="section-kicker">RBAC</span><h1>角色权限</h1><p>管理角色、平台权限字典和用户角色关系。</p></div><el-button class="primary-action" type="primary" @click="openCreate">新增角色</el-button></header><section class="glass-card module-card"><el-tabs><el-tab-pane label="角色"><el-table v-loading="loading" :data="roles"><el-table-column prop="roleCode" label="编码" /><el-table-column prop="roleName" label="名称" /><el-table-column prop="description" label="说明" /><el-table-column label="属性" width="100"><template #default="scope"><el-tag :type="scope.row.builtIn?'warning':'info'">{{ scope.row.builtIn?'内置':'自定义' }}</el-tag></template></el-table-column><el-table-column prop="status" label="状态" width="100" /><el-table-column label="操作" width="210"><template #default="scope"><el-button link @click="openPermissions(scope.row)">授权</el-button><el-button link @click="openEdit(scope.row)">编辑</el-button><el-button v-if="scope.row.status==='DISABLED'&&!scope.row.builtIn" link type="success" @click="restoreRole(scope.row)">启用</el-button><el-button v-else-if="!scope.row.builtIn" link type="danger" @click="removeRole(scope.row)">停用</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="用户角色"><el-table :data="users"><el-table-column prop="username" label="用户名" /><el-table-column prop="displayName" label="姓名" /><el-table-column prop="departmentId" label="部门 ID" /><el-table-column label="操作" width="120"><template #default="scope"><el-button link type="primary" @click="openUserRoles(scope.row)">分配角色</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="权限字典"><el-table :data="permissions"><el-table-column prop="permissionCode" label="权限编码" width="230" /><el-table-column prop="permissionName" label="名称" /><el-table-column prop="resource" label="资源" /><el-table-column prop="action" label="动作" /><el-table-column prop="scope" label="范围" /></el-table></el-tab-pane></el-tabs></section>
<el-dialog v-model="roleVisible" :title="editing?'编辑角色':'新增角色'" width="500px"><el-form label-position="top"><el-form-item v-if="!editing" label="角色编码"><el-input v-model="roleForm.roleCode" /></el-form-item><el-form-item label="角色名称"><el-input v-model="roleForm.roleName" /></el-form-item><el-form-item label="说明"><el-input v-model="roleForm.description" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="roleVisible=false">取消</el-button><el-button type="primary" @click="saveRole">保存</el-button></template></el-dialog>
<el-dialog v-model="permissionVisible" :title="`角色授权 · ${selectedRole?.roleName ?? ''}`" width="620px"><div class="check-list"><el-checkbox v-for="item in permissions" :key="item.id" :model-value="grantedPermissionIds.includes(item.id)" @change="togglePermission(item.id, Boolean($event))"><strong>{{ item.permissionName }}</strong><small>{{ item.permissionCode }} · {{ item.scope }}</small></el-checkbox></div></el-dialog>
<el-dialog v-model="userRoleVisible" :title="`分配角色 · ${selectedUser?.displayName ?? ''}`" width="560px"><div class="check-list"><el-checkbox v-for="item in activeRoles" :key="item.id" :model-value="grantedRoleIds.includes(item.id)" @change="toggleUserRole(item.id, Boolean($event))"><strong>{{ item.roleName }}</strong><small>{{ item.roleCode }}</small></el-checkbox></div></el-dialog></main></template>
